CREATE TABLE `calendarioPagos` (
  `idPago` int NOT NULL AUTO_INCREMENT,
  `empresa` int NOT NULL,
  `concepto` varchar(100) NOT NULL,
  `importe` decimal(10,2) NOT NULL,
  `siFestivo` varchar(45) DEFAULT NULL,
